diff --git a/src/Uinsure.Policies.Api/Contracts/TwoDecimalPlacesConverter.cs b/src/Uinsure.Policies.Api/Contracts/TwoDecimalPlacesConverter.cs
index 97de260..61642a3 100644
--- a/src/Uinsure.Policies.Api/Contracts/TwoDecimalPlacesConverter.cs
+++ b/src/Uinsure.Policies.Api/Contracts/TwoDecimalPlacesConverter.cs
@@ -4,15 +4,28 @@ using System.Text.Json.Serialization;

 namespace Uinsure.Policies.Api.Contracts;

-// Every money amount is written with exactly two decimal places (803.40, not 803.4). Formatting only: "F2" would
-// round a value with more than 2 decimal places, but none reaches it. SellPolicyRequest rejects such an amount
-// with a 400 (judged by value, so 527.180 is accepted and written as 527.18), and stored amounts come only from
-// accepted sales. Reading stays strict: only a JSON number is accepted.
+// Every money amount is written with at least two decimal places (803.40, not 803.4), and never rounded: trailing
+// zeros beyond the second place are dropped (527.180 is 527.18, no value changes) and a value with more
+// significant places is written exactly. Done on the text, because no decimal can hold every amount at scale 2.
+// Reading stays strict: only a JSON number is accepted.
 public sealed class TwoDecimalPlacesConverter : JsonConverter<decimal>
 {
     public override decimal Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options) =>
         reader.TokenType == JsonTokenType.Number ? reader.GetDecimal() : throw new JsonException("Expected a number.");

     public override void Write(Utf8JsonWriter writer, decimal value, JsonSerializerOptions options) =>
-        writer.WriteRawValue(value.ToString("F2", CultureInfo.InvariantCulture));
+        writer.WriteRawValue(PadToTwoPlaces(value.ToString(CultureInfo.InvariantCulture)));
+
+    private static string PadToTwoPlaces(string text)
+    {
+        var point = text.IndexOf('.');
+        if (point < 0)
+        {
+            return text + ".00";
+        }
+
+        var trimmed = text.TrimEnd('0');
+        var places = trimmed.Length - point - 1;
+        return places >= 2 ? trimmed : trimmed + new string('0', 2 - places);
+    }
 }

